291		% the success hypothesis at eps = 1, and the low-degree check of
292		% def:pauli-win-predicate invokes the classical game at ldparams = (q,m,d,1),
293		% whose domain (Definition def:ld-game) requires d >= 1. The hypothesis
294		% propagates to lem:pauli-completeness, thm:pauli, and cor:pauli-binary
295		% through their quantification over admissible tuples.
296		The tuple $\mathsf{qldparams} = (q,m,d)$ is \emph{admissible} if $d \ge 1$, $q$ is an admissible field size (Definition~\ref{def:admissible-size}), and $m$ divides $q$. Since an admissible field size satisfies $q \ge 2$, the divisibility forces $m \ge 1$, so an admissible tuple has all entries positive.
297	\end{definition}
298	
299	\begin{definition}[Question distribution of the Pauli basis test]\label{def:pauli-question-distribution}
300		\uses{def:admissible, def:ld-question-distribution, def:ms-game, def:cl-func, def:cl-dist, def:graph-distribution}
301		% Admissibility of the full tuple is required here, not only the divisibility m | q:
302		% the source parametrizes the Pauli basis test by the tuple qldparams introduced
303		% together with Definition def:admissible (references/qpbt-paper/
304		% 08_classical_and_quantum_low_degree_tests.tex:958-1075), and both the fixed binary
305		% identification of F_q used by the map chi and the trace tr in eq:gamma-value
306		% require q to be a power of 2.
307		The game $\mathfrak{G}^{\mathrm{Pauli}}$ (also $\mathfrak{G}^{\mathrm{Pauli}}_{\mathsf{qldparams}}$) is parametrized by an admissible tuple $\mathsf{qldparams} = (q,m,d)$ (Definition~\ref{def:admissible}): admissibility makes $q$ a power of $2$, so that the field $\F_q$, its fixed identification with binary strings (Chapter~\ref{chap:qpbt-algebra}), and the trace $\tr\colon \F_q \to \F_2$ used by the win predicate below are defined, and it provides the divisibility $m \mid q$ required by the index map $\chi$ of Definition~\ref{def:ld-question-distribution}. The question type set is
308		\begin{equation}
309			\label{eq:pauli-type}
310			\mathcal T^{\mathrm{pauli}} = \bigl( \{\mathsf{Point}, \mathsf{ALine}, \mathsf{DLine}, \mathsf{Pauli}, \mathsf{Pair}\} \times \{X,Z\} \bigr) \cup \mathcal T^{\mathrm{ms}} \cup \{\mathsf{Pair}\}\;,
311		\end{equation}
