591	\label{sec:types}
592	
593	The question distribution of the Pauli basis test is \emph{typed}: each question is a pair consisting of a type, drawn together with the other player's type from the edges of a fixed \emph{type graph}, and a question content, drawn from a CL distribution determined by the pair of types.
594	
595	\begin{definition}[Typed conditionally linear functions]\label{def:typed-cl-functions}
596		\lean{MIPStarRE.QPBT.IsTypedCondLinearFamily}
597		\leanok
598		\uses{def:cl-func}
599		Let $\mathcal T$ be a finite set (the \emph{type set}) and let $V$ be $\F^n$ for some integer $n \ge 0$. A \emph{$\mathcal T$-typed family of $\ell$-level conditionally linear functions} (implicitly, \emph{on $V$}) is a collection $\{L_t\}_{t \in \mathcal T}$ such that, for each $t \in \mathcal T$, $L_t$ is an $\ell$-level conditionally linear function on $V$.
600	\end{definition}
601	
602	% Nonemptiness of the edge set is stated explicitly here: with E empty, m = k = 0 and the
603	% normalization 1/(2m-k) below is undefined. The source
604	% (references/qpbt-paper/07_types.tex:65-82) leaves this boundary hypothesis implicit.
605	\begin{definition}[Graph distribution]\label{def:graph-distribution}
606		Let $G = (U, E)$ be an undirected graph with vertex set $U$ and nonempty edge set $E$. Edges in $E$ are written as multisets $\{u, v\}$ of two vertices; the case $u = v$ represents a self-loop. Suppose there are $m \ge 1$ edges, $k$ of which are self-loops. Then the \emph{graph distribution $\mu_G$ of $G$} is the distribution over $U \times U$ such that for every $(u,v) \in U \times U$,
607		\[
608			\mu_G(u, v) =
609			\begin{cases}
610				1/(2m-k) & \text{if } \{u,v\} \in E\,,\\
611				0 & \text{otherwise}\,.
612			\end{cases}
613		\]
614		This is identical to the uniform distribution over ordered pairs $(u,v) \in U \times U$ such that $\{u,v\} \in E$: each edge that is not a self-loop contributes two ordered pairs, and each self-loop contributes one, whence the normalization $2m-k$.
615	\end{definition}
616	
617	% The nonempty-edge hypothesis on G is inherited from def:graph-distribution, where it is
618	% needed for the graph distribution mu_G to be defined; the source
619	% (references/qpbt-paper/07_types.tex:84-93) leaves it implicit here as well.
620	\begin{definition}[Typed conditionally linear distributions]\label{def:typed-cl-distributions}
621		\lean{MIPStarRE.QPBT.typedCLDistribution, MIPStarRE.QPBT.ldQuestionDistribution_eq_typedCL, MIPStarRE.QPBT.pauliQuestionDistribution_eq_typedCL}
622		\leanok
623		\uses{def:typed-cl-functions, def:graph-distribution, def:cl-dist}
624		Let $\mathcal T$ be a type set and let $L = \{L_u\}_{u \in \mathcal T}$ and $R = \{R_v\}_{v \in \mathcal T}$ be $\mathcal T$-typed families of conditionally linear functions on $V$. Let $G = (\mathcal T, E)$ be a graph with vertex set $\mathcal T$ and nonempty edge set $E$, so that the graph distribution $\mu_G$ of Definition~\ref{def:graph-distribution} is defined. The \emph{$(\mathcal T, G)$-typed conditionally linear distribution $\mu^G_{L,\,R}$ corresponding to $(L, R)$} is the distribution over pairs $\bigl( (u, x), (v, y) \bigr)$, where the type pair $(u,v)$ is drawn from the graph distribution $\mu_G$ and the content pair $(x,y)$ is drawn from $\mu_{L_u,\,R_v}$.
625	\end{definition}

